diff --git a/packages/core/test/editable-text/editableTextTests.tsx b/packages/core/test/editable-text/editableTextTests.tsx
index 6e10eb4cf00..0bf36ced7f6 100644
--- a/packages/core/test/editable-text/editableTextTests.tsx
+++ b/packages/core/test/editable-text/editableTextTests.tsx
@@ -310,4 +310,30 @@ describe("<EditableText>", () => {
             wrapper.find("textarea").simulate("change", { target: { value } }).simulate("keydown", e);
         }
     });
+
+    describe("custom attributes", () => {
+        const customProps = {
+            "aria-label": "Edit description",
+            "data-gramm": "false",
+            spellcheck: "false",
+        };
+
+        it("passes custom attributes to textarea when multiline is true", () => {
+            const wrapper = mount(
+                <EditableText isEditing={true} multiline={true} customInputAttributes={customProps} />,
+            ).find("textarea");
+            assert.strictEqual(wrapper.prop("data-gramm"), "false");
+            assert.strictEqual(wrapper.prop("spellcheck"), "false");
+            assert.strictEqual(wrapper.prop("aria-label"), "Edit description");
+        });
+
+        it("passes custom attributes to input when multiline is false", () => {
+            const wrapper = mount(
+                <EditableText isEditing={true} multiline={false} customInputAttributes={customProps} />,
+            ).find("input");
+            assert.strictEqual(wrapper.prop("data-gramm"), "false");
+            assert.strictEqual(wrapper.prop("spellcheck"), "false");
+            assert.strictEqual(wrapper.prop("aria-label"), "Edit description");
+        });
+    });
 });

issue_statement:
#### Environment

@blueprintjs/core: 5.10.5

#### Feature request

We need to enhance the EditableText component from BlueprintJS to allow the addition of custom HTML attributes to its underlying textarea element. This feature is crucial for improving the component's flexibility and compatibility with various browser extensions and accessibility requirements. `data-`, `spellcheck`, `aria-`, and other standard HTML attributes.

#### Examples

```
<EditableText
  value={text}
  onChange={handleChange}
  textareaAttributes={{
    'data-gramm': 'false',  // Disable Grammarly
    'spellcheck': 'false',  // Disable browser spellcheck
    'aria-label': 'Edit description',  // Improve accessibility
  }}
/>
```

